export type WorkerToolCallTimingStatus = 'success' | 'error'

export type WorkerToolCallTimingEvent = {
  readonly source_namespace: string
  readonly tool_name: string
  readonly worker_tool_call_total_ms: number
  readonly worker_tool_call_latency_bucket: string
  readonly worker_tool_call_status: WorkerToolCallTimingStatus
}

export type WorkerToolCallTimingSummary = {
  readonly worker_tool_calls_count: number
  readonly worker_tool_calls_sum_ms: number
  readonly worker_tool_calls_max_ms: number
}

export function emptyWorkerToolCallTimingSummary(): WorkerToolCallTimingSummary {
  return {
    worker_tool_calls_count: 0,
    worker_tool_calls_sum_ms: 0,
    worker_tool_calls_max_ms: 0,
  }
}

export class WorkerToolCallTimingCollector {
  #count = 0
  #sumMs = 0
  #maxMs = 0

  record(durationMs: number): WorkerToolCallTimingSummary {
    const normalized = normalizeDurationMs(durationMs)
    this.#count += 1
    this.#sumMs += normalized
    this.#maxMs = Math.max(this.#maxMs, normalized)
    return this.snapshot()
  }

  snapshot(): WorkerToolCallTimingSummary {
    return {
      worker_tool_calls_count: this.#count,
      worker_tool_calls_sum_ms: this.#sumMs,
      worker_tool_calls_max_ms: this.#maxMs,
    }
  }
}

export function workerToolCallTimingEvent(args: {
  readonly sourceNamespace: string
  readonly toolName: string
  readonly durationMs: number
  readonly status: WorkerToolCallTimingStatus
}): WorkerToolCallTimingEvent {
  const durationMs = normalizeDurationMs(args.durationMs)
  return {
    source_namespace: args.sourceNamespace,
    tool_name: args.toolName,
    worker_tool_call_total_ms: durationMs,
    worker_tool_call_latency_bucket: latencyBucket(durationMs),
    worker_tool_call_status: args.status,
  }
}

function normalizeDurationMs(value: number): number {
  if (!Number.isFinite(value) || value < 0) return 0
  return Math.round(value)
}

function latencyBucket(durationMs: number): string {
  if (durationMs < 1_000) return 'lt_1s'
  if (durationMs < 3_000) return '1s_3s'
  if (durationMs < 10_000) return '3s_10s'
  if (durationMs < 30_000) return '10s_30s'
  return 'gte_30s'
}
